{"file_text":"use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OptionConfig {
    #[serde(default)]
    pub key: String,
    #[serde(default)]
    pub full: String,
    pub abbr: Option<String>,
    #[serde(default)]
    pub flag: bool,
    pub default: Option<serde_json::Value>,
    pub default_help: Option<String>,
    pub choices: Option<Vec<String>>,
    pub help: Option<String>,
    pub metavar: Option<String>,
    #[serde(default)]
    pub list: bool,
    pub display_index: Option<i32>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ParseResult {
    pub positional_arguments: Vec<serde_json::Value>,
    pub options: serde_json::Map<String, serde_json::Value>,
}

#[derive(Debug, Clone)]
pub struct ArgsParserError {
    pub exit_code: i32,
    pub message: String,
}

impl std::fmt::Display for ArgsParserError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl std::error::Error for ArgsParserError {}

pub fn format_option(opt: &OptionConfig) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = &opt.abbr {
        text.push('-');
        text.push_str(abbr);
        text.push_str(", ");
    } else {
        text.push_str("    ");
    }

    text.push_str("--");
    if opt.flag {
        text.push_str("(no-)");
    }
    let full_name = if opt.full.is_empty() {
        &opt.key
    } else {
        &opt.full
    };
    text.push_str(full_name);

    if let Some(choices) = &opt.choices {
        text.push('=');
        text.push_str(&choices.join("|"));
    } else if let Some(metavar) = &opt.metavar {
        text.push('=');
        text.push_str(metavar);
    }

    if opt.list {
        text.push_str(" ...");
    }

    let has_default = opt.default_help.is_some() || opt.default.is_some();
    if has_default || opt.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            let padding = 32 - text.len();
            text.push_str(&" ".repeat(padding));
        }
        let text_length = text.len();
        if let Some(help) = &opt.help {
            text.push_str(help);
        }
        if has_default {
            if opt.help.is_some() {
                text.push('\n');
            }
            let default_str = if let Some(dh) = &opt.default_help {
                dh.clone()
            } else if let Some(d) = &opt.default {
                match d {
                    serde_json::Value::String(s) => s.clone(),
                    serde_json::Value::Bool(b) => b.to_string(),
                    serde_json::Value::Number(n) => n.to_string(),
                    _ => d.to_string(),
                }
            } else {
                String::new()
            };
            text.push_str(&" ".repeat(text_length));
            text.push_str(&format!("(default: {})", default_str));
        }
    }

    text
}

pub fn get_help_text(options_map: &BTreeMap<String, OptionConfig>) -> String {
    let mut opts: Vec<OptionConfig> = options_map
        .iter()
        .map(|(k, v)| {
            let mut opt = v.clone();
            if opt.key.is_empty() {
                opt.key = k.clone();
            }
            if opt.full.is_empty() {
                opt.full = k.clone();
            }
            opt
        })
        .collect();

    // Sort by display_index (None values sorted after or with high index)
    opts.sort_by_key(|o| o.display_index.unwrap_or(i32::MAX));

    let options_formatted: Vec<String> = opts.iter().map(format_option).collect();

    let text = format!(
        "Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
\"...\" behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{}",
        options_formatted.join("\n")
    );

    text
}

fn is_option(arg: &str) -> bool {
    arg.starts_with("--") || (arg.starts_with('-') && arg.len() > 1)
}

fn parse_value(v: &str) -> serde_json::Value {
    if let Ok(parsed) = serde_json::from_str::<serde_json::Value>(v) {
        // Only return parsed json if it's not a bare string that was parsed
        match parsed {
            serde_json::Value::Number(_)
            | serde_json::Value::Bool(_)
            | serde_json::Value::Array(_)
            | serde_json::Value::Object(_) => parsed,
            _ => serde_json::Value::String(v.to_string()),
        }
    } else {
        serde_json::Value::String(v.to_string())
    }
}

pub fn parse_args(
    options_map: &mut BTreeMap<String, OptionConfig>,
    args: &[String],
) -> std::result::Result<ParseResult, ArgsParserError> {
    // Add help option if not present
    if !options_map.contains_key("help") {
        options_map.insert(
            "help".to_string(),
            OptionConfig {
                key: "help".to_string(),
                full: "help".to_string(),
                abbr: Some("h".to_string()),
                flag: true,
                default: None,
                default_help: None,
                choices: None,
                help: Some("print this help and exit".to_string()),
                metavar: None,
                list: false,
                display_index: Some(5),
            },
        );
    }

    let help_text = get_help_text(options_map);

    // Build lookup table for flags
    let mut lookup: BTreeMap<String, OptionConfig> = BTreeMap::new();
    for (k, v) in options_map.iter() {
        let mut opt = v.clone();
        if opt.key.is_empty() {
            opt.key = k.clone();
        }
        if opt.full.is_empty() {
            opt.full = k.clone();
        }

        lookup.insert(format!("--{}", opt.full), opt.clone());
        if let Some(abbr) = &opt.abbr {
            lookup.insert(format!("-{}", abbr), opt.clone());
        }
        if opt.flag {
            lookup.insert(format!("--no-{}", opt.full), opt.clone());
        }
    }

    let mut parsed_options: serde_json::Map<String, serde_json::Value> = serde_json::Map::new();
    let mut positional_arguments: Vec<serde_json::Value> = Vec::new();

    // Set defaults
    for (opt_name, opt) in options_map.iter() {
        if let Some(default_val) = &opt.default {
            parsed_options.insert(opt_name.clone(), default_val.clone());
        } else if opt.list {
            parsed_options.insert(opt_name.clone(), serde_json::Value::Array(Vec::new()));
        }
    }

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;

            if let Some(idx) = arg.find('=') {
                option_name = arg[..idx].to_string();
                value = Some(arg[idx + 1..].to_string());
            }

            let option = if let Some(opt) = lookup.get(&option_name) {
                opt.clone()
            } else {
                // Unknown option
                let real_option_name = option_name
                    .trim_start_matches("--")
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    .to_string();

                let is_list = parsed_options
                    .get(&real_option_name)
                    .map(|v| !v.is_boolean())
                    .unwrap_or(false);

                let is_flag = !parsed_options.contains_key(&real_option_name)
                    && value.is_none()
                    && (i + 1 >= args.len() || is_option(&args[i + 1]));

                let opt = OptionConfig {
                    key: real_option_name.clone(),
                    full: real_option_name.clone(),
                    abbr: None,
                    flag: is_flag,
                    default: None,
                    default_help: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    list: is_list,
                    display_index: None,
                };

                if is_list {
                    if let Some(current_val) = parsed_options.get(&real_option_name) {
                        if !current_val.is_array() {
                            let new_arr = if current_val.as_bool() == Some(true) {
                                Vec::new()
                            } else {
                                vec![current_val.clone()]
                            };
                            parsed_options
                                .insert(real_option_name.clone(), serde_json::Value::Array(new_arr));
                        }
                    }
                }

                opt
            };

            if option.key == "help" {
                return Err(ArgsParserError {
                    exit_code: 0,
                    message: help_text,
                });
            }

            if option.flag {
                let bool_val = if option_name.starts_with("--no-") {
                    false
                } else if let Some(v) = value {
                    v == "1" || v == "true"
                } else {
                    true
                };
                parsed_options.insert(option.key.clone(), serde_json::Value::Bool(bool_val));
            } else {
                if value.is_none() && i < args.len() - 1 && !is_option(&args[i + 1]) {
                    i += 1;
                    value = Some(args[i].clone());
                }

                if let Some(v) = value {
                    let parsed_v = parse_value(&v);
                    if option.list {
                        let arr = parsed_options
                            .entry(option.key.clone())
                            .or_insert_with(|| serde_json::Value::Array(Vec::new()));
                        if let serde_json::Value::Array(vec) = arr {
                            vec.push(parsed_v);
                        }
                    } else {
                        parsed_options.insert(option.key.clone(), parsed_v);
                    }
                } else {
                    // Missing value
                    let full_name = if option.full.is_empty() {
                        &option.key
                    } else {
                        &option.full
                    };
                    return Err(ArgsParserError {
                        exit_code: 1,
                        message: format!(
                            "Missing value: --{} requires a value\n\n---\n\n{}",
                            full_name, help_text
                        ),
                    });
                }
            }
        } else {
            // Positional argument
            if let Ok(num) = arg.parse::<i64>() {
                if arg.chars().all(|c| c.is_ascii_digit()) {
                    positional_arguments.push(serde_json::Value::Number(serde_json::Number::from(num)));
                } else {
                    positional_arguments.push(serde_json::Value::String(arg.clone()));
                }
            } else {
                positional_arguments.push(serde_json::Value::String(arg.clone()));
            }
        }
        i += 1;
    }

    // Validate choices
    let mut errors: Vec<String> = Vec::new();
    for (opt_name, opt) in options_map.iter() {
        if let Some(choices) = &opt.choices {
            if let Some(val) = parsed_options.get(opt_name) {
                let val_str = match val {
                    serde_json::Value::String(s) => s.as_str(),
                    _ => "",
                };
                if !choices.iter().any(|c| c == val_str) {
                    let full_name = if opt.full.is_empty() {
                        opt_name
                    } else {
                        &opt.full
                    };
                    errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        full_name,
                        choices.join(",")
                    ));
                }
            }
        }
    }

    if !errors.is_empty() {
        return Err(ArgsParserError {
            exit_code: 1,
            message: format!("{}\n\n---\n\n{}", errors.join("\n"), help_text),
        });
    }

    Ok(ParseResult {
        positional_arguments,
        options: parsed_options,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_args_parser_basics() {
        let mut opts = BTreeMap::new();
        opts.insert(
            "transform".to_string(),
            OptionConfig {
                key: "transform".to_string(),
                full: "transform".to_string(),
                abbr: Some("t".to_string()),
                flag: false,
                default: Some(serde_json::Value::String("./transform.js".to_string())),
                default_help: None,
                choices: None,
                help: Some("path to the transform file".to_string()),
                metavar: Some("TRANSFORM_PATH".to_string()),
                list: false,
                display_index: Some(1),
            },
        );
        opts.insert(
            "dry".to_string(),
            OptionConfig {
                key: "dry".to_string(),
                full: "dry".to_string(),
                abbr: Some("d".to_string()),
                flag: true,
                default: Some(serde_json::Value::Bool(false)),
                default_help: None,
                choices: None,
                help: Some("dry run".to_string()),
                metavar: None,
                list: false,
                display_index: Some(2),
            },
        );

        let args = vec![
            "-t".to_string(),
            "myTransform.js".to_string(),
            "-d".to_string(),
            "file1.js".to_string(),
            "file2.js".to_string(),
        ];

        let result = parse_args(&mut opts, &args).unwrap();
        assert_eq!(
            result.options.get("transform").unwrap().as_str().unwrap(),
            "myTransform.js"
        );
        assert_eq!(
            result.options.get("dry").unwrap().as_bool().unwrap(),
            true
        );
        assert_eq!(result.positional_arguments.len(), 2);
    }
}
