{"path":"/workspace/codebase/native/src/ignore_files.rs","command":"create","file_text":"use regex::Regex;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, Default)]
pub struct IgnoreFiles {
    matchers: Vec<String>,
    regexes: Vec<Regex>,
}

impl IgnoreFiles {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_ignore_pattern(&mut self, val: &str) {
        let pattern = val.trim();
        if pattern.is_empty() || pattern.starts_with('#') {
            return;
        }

        let mut patterns_to_add = Vec::new();
        if !pattern.contains('/') {
            patterns_to_add.push(format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            patterns_to_add.push(format!("**/{}**", pattern));
            patterns_to_add.push(format!("{}**", pattern));
        }
        patterns_to_add.push(pattern.to_string());

        for p in patterns_to_add {
            if let Some(re) = glob_to_regex(&p) {
                self.matchers.push(p);
                self.regexes.push(re);
            }
        }
    }

    pub fn add_from_input(&mut self, patterns: &[String]) {
        for pattern in patterns {
            self.add_ignore_pattern(pattern);
        }
    }

    pub fn add_from_file(&mut self, file_path: &Path) {
        if let Ok(content) = fs::read_to_string(file_path) {
            for line in content.lines() {
                self.add_ignore_pattern(line);
            }
        }
    }

    pub fn should_ignore(&self, path_str: &str) -> bool {
        if self.regexes.is_empty() {
            return false;
        }

        // Normalize slashes
        let clean_path = path_str.replace('\\', "/");

        // Strip leading ../ or ./ traversal segments
        let re_prefix = Regex::new(r"^(?:\.\.?[/\\])+").unwrap();
        let normalized_path = re_prefix.replace_all(&clean_path, "").to_string();

        for re in &self.regexes {
            if re.is_match(&clean_path) || (normalized_path != clean_path && re.is_match(&normalized_path)) {
                return true;
            }
        }
        false
    }
}

pub fn glob_to_regex(glob: &str) -> Option<Regex> {
    let mut pattern = glob.replace('\\', "/");
    // Trim leading / if needed
    let anchored_start = pattern.starts_with('/');
    if anchored_start {
        pattern = pattern[1..].to_string();
    }

    let mut re_str = String::from("^");
    if !anchored_start && !pattern.starts_with("**/") {
        // pattern can match anywhere if no slash or relative
    }

    let mut i = 0;
    let chars: Vec<char> = pattern.chars().collect();
    let len = chars.len();

    while i < len {
        let c = chars[i];
        if c == '*' {
            if i + 1 < len && chars[i + 1] == '*' {
                // `**`
                i += 2;
                if i < len && chars[i] == '/' {
                    // `**/`
                    i += 1;
                    re_str.push_str("(?:.*/)?");
                } else if i == len {
                    // trailing `**`
                    re_str.push_str(".*");
                } else {
                    re_str.push_str(".*");
                }
                continue;
            } else {
                // single `*`
                re_str.push_str("[^/]*");
                i += 1;
                continue;
            }
        } else if c == '?' {
            re_str.push_str("[^/]");
            i += 1;
            continue;
        } else if c == '.' || c == '+' || c == '(' || c == ')' || c == '^' || c == '$' || c == '|' || c == '{' || c == '}' || c == '[' || c == ']' {
            re_str.push('\\');
            re_str.push(c);
        } else {
            re_str.push(c);
        }
        i += 1;
    }

    re_str.push('$');

    Regex::new(&re_str).ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_ignore_pattern_no_slash() {
        let mut ignore = IgnoreFiles::new();
