{"command":"create","path":"/workspace/codebase/native/src/match_node.rs","file_text":"use napi::bindgen_prelude::*;
use napi_derive::napi;
use regex::Regex;

pub fn match_json_value(haystack: &serde_json::Value, needle: &serde_json::Value) -> bool {
    match (haystack, needle) {
        (serde_json::Value::Object(h_obj), serde_json::Value::Object(n_obj)) => {
            for (k, n_val) in n_obj {
                if let Some(h_val) = h_obj.get(k) {
                    if !match_json_value(h_val, n_val) {
                        return false;
                    }
                } else {
                    return false;
                }
            }
            true
        }
        (serde_json::Value::Array(h_arr), serde_json::Value::Array(n_arr)) => {
            if h_arr.len() < n_arr.len() {
                return false;
            }
            for (i, n_val) in n_arr.iter().enumerate() {
                if !match_json_value(&h_arr[i], n_val) {
                    return false;
                }
            }
            true
        }
        (h, n) => h == n,
    }
}

/// Dynamic match function for JS / N-API
pub fn match_js_node(env: &Env, haystack: JsUnknown, needle: JsUnknown) -> Result<bool> {
    let needle_type = needle.get_type()?;

    if needle_type == ValueType::Function {
        let func: JsFunction = unsafe { needle.cast() };
        let result = func.call(None, &[haystack])?;
        return result.coerce_to_bool()?.get_value();
    }

    if needle_type == ValueType::Object {
        let needle_obj: JsObject = unsafe { needle.cast() };

        // Check if RegExp
        let constructor: JsFunction = needle_obj.get_named_property("constructor")?;
        let constructor_name: String = constructor.get_named_property("name")?;
        if constructor_name == "RegExp" {
            let test_fn: JsFunction = needle_obj.get_named_property("test")?;
            let result = test_fn.call(Some(&needle_obj), &[haystack])?;
            return result.coerce_to_bool()?.get_value();
        }

        // Check if Array
        let is_array_fn: JsFunction = env.get_global()?.get_named_property::<JsObject>("Array")?.get_named_property("isArray")?;
        let needle_is_array = is_array_fn.call(None, &[needle])?.coerce_to_bool()?.get_value()?;

        if needle_is_array {
            let haystack_is_array = is_array_fn.call(None, &[haystack])?.coerce_to_bool()?.get_value()?;
            if !haystack_is_array {
                return Ok(false);
            }

            let needle_arr = needle_obj;
            let haystack_arr: JsObject = unsafe { haystack.cast() };

            let n_len: u32 = needle_arr.get_array_length()?;
            let h_len: u32 = haystack_arr.get_array_length()?;

            if h_len < n_len {
                return Ok(false);
            }

            for i in 0..n_len {
                let n_elem: JsUnknown = needle_arr.get_element(i)?;
                let h_elem: JsUnknown = haystack_arr.get_element(i)?;
                if !match_js_node(env, h_elem, n_elem)? {
                    return Ok(false);
                }
            }
            return Ok(true);
        }

        // Object matching
        if haystack.get_type()? != ValueType::Object {
            return Ok(false);
        }

        let mut h_obj: JsObject = unsafe { haystack.cast() };

        // Check if NodePath (has .get function or .value property)
        if h_obj.has_named_property("value")? && h_obj.has_named_property("get")? {
            let get_prop: JsUnknown = h_obj.get_named_property("get")?;
            if get_prop.get_type()? == ValueType::Function {
                h_obj = h_obj.get_named_property("value")?;
            }
        }

        let prop_names: JsObject = needle_obj.get_property_names()?;
        let prop_len: u32 = prop_names.get_array_length()?;

        for i in 0..prop_len {
            let key_js: JsString = prop_names.get_element(i)?;
            let key_str = key_js.into_utf8()?.into_owned()?;

            if !h_obj.has_named_property(&key_str)? {
                return Ok(false);
            }

            let n_val: JsUnknown = needle_obj.get_named_property(&key_str)?;
            let h_val: JsUnknown = h_obj.get_named_property(&key_str)?;

            if !match_js_node(env, h_val, n_val)? {
                return Ok(false);
            }
        }

        return Ok(true);
    }

    // Strict equality comparison for primitives
    let strict_eq_fn = env.get_global()?.get_named_property::<JsObject>("Object")?.get_named_property::<JsFunction>("is")?;
    let is_eq = strict_eq_fn.call(None, &[haystack, needle])?.coerce_to_bool()?.get_value()?;
    Ok(is_eq)
}

#[napi(js_name = "matchNode")]
pub fn js_match_node(env: Env, haystack: JsUnknown, needle: JsUnknown) -> Result<bool> {
    match_js_node(&env, haystack, needle)
}
"}

