pub fn build_interpolated_source(template_strings: &[String], var_names: &[String]) -> String {
    if template_strings.is_empty() {
        return String::new();
    }
    let mut result = template_strings[0].clone();
    for i in 1..template_strings.len() {
        if i - 1 < var_names.len() {
            result.push_str(&var_names[i - 1]);
        }
        result.push_str(&template_strings[i]);
    }
    result
}

