{"path":"/workspace/codebase/native/src/file_discovery.rs","file_text":"use crate::ignore_files::IgnoreFiles;
use std::fs;
use std::path::{Path, PathBuf};

pub fn get_all_files(
    paths: &[String],
    extensions: Option<&[String]>,
    ignore: &IgnoreFiles,
) -> Vec<String> {
    let mut result = Vec::new();

    for p_str in paths {
        let path = Path::new(p_str);
        match fs::metadata(path) {
            Err(_) => {
                eprintln!("Skipping path {} which does not exist.", p_str);
            }
            Ok(meta) => {
                if meta.is_dir() {
                    collect_dir_files(path, extensions, ignore, &mut result);
                } else if meta.is_file() {
                    if is_matching_file(path, extensions) && !ignore.should_ignore(p_str) {
                        result.push(p_str.clone());
                    }
                }
            }
        }
    }

    result
}

fn collect_dir_files(
    dir: &Path,
    extensions: Option<&[String]>,
    ignore: &IgnoreFiles,
    acc: &mut Vec<String>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut sorted_entries: Vec<PathBuf> = Vec::new();
    for entry in entries.flatten() {
        sorted_entries.push(entry.path());
    }
    sorted_entries.sort();

    for path in sorted_entries {
        let path_str = path.to_string_lossy().to_string();
        // Check symlink / stat
        match fs::metadata(&path) {
            Err(_) => {
                println!("Skipping path \"{}\" which does not exist.", path_str);
            }
            Ok(meta) => {
                if ignore.should_ignore(&path_str) {
                    continue;
                }
                if meta.is_dir() {
                    collect_dir_files(&path, extensions, ignore, acc);
                } else if meta.is_file() && is_matching_file(&path, extensions) {
                    acc.push(path_str);
                }
            }
        }
    }
}

fn is_matching_file(path: &Path, extensions: Option<&[String]>) -> bool {
    if let Some(exts) = extensions {
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            let dot_ext = format!(".{}", ext);
            exts.iter().any(|e| e == &dot_ext || e == ext)
        } else {
            false
        }
    } else {
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_file_filter_match() {
        let p = Path::new("src/index.js");
        let exts = vec![".js".to_string(), ".ts".to_string()];
        assert!(is_matching_file(p, Some(&exts)));

        let p_rs = Path::new("src/index.rs");
        assert!(!is_matching_file(p_rs, Some(&exts)));
    }
}
