#[napi(js_name = "parseArgs")]
pub fn js_parse_args(env: Env, options_json: String, args: Vec<String>) -> Result<JsObject> {
    let mut options_map: BTreeMap<String, args_parser::OptionConfig> =
        serde_json::from_str(&options_json)
            .map_err(|e| Error::new(Status::InvalidArg, format!("Invalid options JSON: {}", e)))?;

    match args_parser::parse_args(&mut options_map, &args) {
        Ok(result) => {
            let res_json = serde_json::to_string(&result)
                .map_err(|e| Error::new(Status::GenericFailure, e.to_string()))?;
            let json_global: JsObject = env.get_global()?.get_named_property("JSON")?;
            let json_parse: JsFunction = json_global.get_named_property("parse")?;
            let js_str = env.create_string(&res_json)?;
            let parsed = json_parse.call(None, &[js_str.into_unknown()])?;
            parsed.coerce_to_object()
        }
        Err(err) => {
            let mut js_err = Error::new(Status::GenericFailure, err.message);
            // In napi, we can throw error or return structured error
            Err(js_err)
        }
    }
}

#[napi(js_name = "getHelpText")]
pub fn js_get_help_text(options_json: String) -> Result<String> {
    let options_map: BTreeMap<String, args_parser::OptionConfig> =
        serde_json::from_str(&options_json)
            .map_err(|e| Error::new(Status::InvalidArg, format!("Invalid options JSON: {}", e)))?;
    Ok(args_parser::get_help_text(&options_map))
}

#[napi(js_name = "NativeIgnoreFiles")]
pub struct NativeIgnoreFiles {
    inner: ignore_files::IgnoreFiles,
}

#[napi]
impl NativeIgnoreFiles {
    #[napi(constructor)]
    pub fn new() -> Self {
        Self {
            inner: ignore_files::IgnoreFiles::new(),
        }
    }

    #[napi]
    pub fn add(&mut self, input: JsUnknown) -> Result<()> {
        if input.is_buffer()? || input.get_type()? == ValueType::String {
            let s: JsString = unsafe { input.cast() };
            let val = s.into_utf8()?.into_owned()?;
            self.inner.add_ignore_pattern(&val);
        } else if input.get_type()? == ValueType::Object {
            let obj: JsObject = unsafe { input.cast() };
            let len: u32 = obj.get_array_length().unwrap_or(0);
            for i in 0..len {
                if let Ok(elem) = obj.get_element::<JsString>(i) {
                    if let Ok(val) = elem.into_utf8() {
                        self.inner.add_ignore_pattern(&val.into_owned().unwrap_or_default());
                    }
                }
            }
        }
        Ok(())
    }

    #[napi(js_name = "addFromFile")]
    pub fn add_from_file(&mut self, input: JsUnknown) -> Result<()> {
        if input.get_type()? == ValueType::String {
            let s: JsString = unsafe { input.cast() };
            let val = s.into_utf8()?.into_owned()?;
            self.inner.add_from_file(Path::new(&val));
        } else if input.get_type()? == ValueType::Object {
            let obj: JsObject = unsafe { input.cast() };
            let len: u32 = obj.get_array_length().unwrap_or(0);
            for i in 0..len {
                if let Ok(elem) = obj.get_element::<JsString>(i) {
                    if let Ok(val) = elem.into_utf8() {
                        if let Ok(path_str) = val.into_owned() {
                            self.inner.add_from_file(Path::new(&path_str));
                        }
                    }
                }
            }
        }
        Ok(())
    }

    #[napi(js_name = "shouldIgnore")]
    pub fn should_ignore(&self, path: String) -> bool {
        self.inner.should_ignore(&path)
    }
}

