{"path":"/workspace/codebase/native/src/utils.rs","command":"create","file_text":"use napi::bindgen_prelude::*;
use napi_derive::napi;
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};

pub fn require_package_from_dir(name: &str, start_dir: &Path) -> serde_json::Value {
    let mut current = if start_dir.is_file() {
        start_dir.parent().map(|p| p.to_path_buf())
    } else {
        Some(start_dir.to_path_buf())
    };

    while let Some(dir) = current {
        let pkg_path = dir.join("package.json");
        if pkg_path.is_file() {
            if let Ok(content) = fs::read_to_string(&pkg_path) {
                if let Ok(val) = serde_json::from_str::<serde_json::Value>(&content) {
                    if let Some(pkg_name) = val.get("name").and_then(|n| n.as_str()) {
                        if pkg_name == name {
                            return val;
                        }
                    }
                }
            }
        }
        current = dir.parent().map(|p| p.to_path_buf());
    }

    serde_json::Value::Object(serde_json::Map::new())
}

#[napi(js_name = "requirePackage")]
pub fn js_require_package(name: String, start_dir: Option<String>) -> Result<serde_json::Value> {
    let dir_path = if let Some(d) = start_dir {
        PathBuf::from(d)
    } else {
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    };

    Ok(require_package_from_dir(&name, &dir_path))
}

pub fn intersection_vecs<T: Clone + PartialEq>(arrays: &[Vec<T>]) -> Vec<T> {
    if arrays.is_empty() {
        return Vec::new();
    }
    let mut result = arrays[0].clone();
    for arr in &arrays[1..] {
        result.retain(|item| arr.contains(item));
    }
    result
}

pub fn union_vecs<T: Clone + std::hash::Hash + Eq>(arrays: &[Vec<T>]) -> Vec<T> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    for arr in arrays {
        for item in arr {
            if seen.insert(item.clone()) {
                result.push(item.clone());
            }
        }
    }
    result
}

#[napi(js_name = "intersection")]
pub fn js_intersection(arrays: Vec<Vec<serde_json::Value>>) -> Vec<serde_json::Value> {
    intersection_vecs(&arrays)
}

#[napi(js_name = "union")]
pub fn js_union(arrays: Vec<Vec<serde_json::Value>>) -> Vec<serde_json::Value> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    for arr in arrays {
        for item in arr {
            let key = serde_json::to_string(&item).unwrap_or_default();
            if seen.insert(key) {
                result.push(item);
            }
        }
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_intersection() {
        let a = vec![1, 2, 3, 4];
        let b = vec![2, 3, 5];
        let c = vec![3, 2, 6];
        assert_eq!(intersection_vecs(&[a, b, c]), vec![2, 3]);
    }

    #[test]
    fn test_union() {
        let a = vec![1, 2, 3];
        let b = vec![2, 3, 4, 5];
        let c = vec![5, 6];
        assert_eq!(union_vecs(&[a, b, c]), vec![1, 2, 3, 4, 5, 6]);
    }
}
