pub fn match_json_value(haystack: &serde_json::Value, needle: &serde_json::Value) -> bool {
    match (haystack, needle) {
        (serde_json::Value::Object(h_obj), serde_json::Value::Object(n_obj)) => {
            for (k, n_val) in n_obj {
                if let Some(h_val) = h_obj.get(k) {
                    if !match_json_value(h_val, n_val) {
                        return false;
                    }
                } else {
                    return false;
                }
            }
            true
        }
        (serde_json::Value::Array(h_arr), serde_json::Value::Array(n_arr)) => {
            if h_arr.len() < n_arr.len() {
                return false;
            }
            for (i, n_val) in n_arr.iter().enumerate() {
                if !match_json_value(&h_arr[i], n_val) {
                    return false;
                }
            }
            true
        }
        (h, n) => h == n,
    }
}

