fn match_node_inner(env: &Env, haystack: &JsUnknown, needle: &JsUnknown) -> Result<bool> {
    let needle_type = needle.get_type()?;
    if needle_type == ValueType::Function {
        let func = unsafe { needle.cast::<JsFunction>() };
        let res = func.call(None, &[haystack])?;
        let bool_res = res.coerce_to_bool()?.get_value()?;
        return Ok(bool_res);
    }
    let haystack_type = haystack.get_type()?;
    if needle_type == ValueType::Object && haystack_type == ValueType::Object {
        let needle_is_null = needle.is_null()?;
        let haystack_is_null = haystack.is_null()?;
        if needle_is_null || haystack_is_null {
            return Ok(needle_is_null && haystack_is_null);
        }
        let needle_obj = unsafe { needle.cast::<JsObject>() };
        let haystack_obj = unsafe { haystack.cast::<JsObject>() };

        let prop_names = JsObject::get_property_names(&needle_obj)?;
        let len = prop_names.get_array_length()?;
        for i in 0..len {
            let prop_key: JsUnknown = prop_names.get_element(i)?;
            let prop_str = prop_key.coerce_to_string()?.into_utf8()?.as_str()?.to_string();
            if !haystack_obj.has_own_property(&prop_str)? {
                return Ok(false);
            }
            let h_val: JsUnknown = haystack_obj.get_named_property(&prop_str)?;
            let n_val: JsUnknown = needle_obj.get_named_property(&prop_str)?;
            if !match_node_inner(env, &h_val, &n_val)? {
                return Ok(false);
