pub fn js_intersection(env: Env, arrays: Vec<Unknown>) -> Result<Unknown> {
    if arrays.is_empty() {
        let empty_arr = env.create_array(0)?;
        return Ok(empty_arr.into_unknown());
    }
    let first = arrays[0];
    if first.get_type()? != ValueType::Object || !first.is_array()? {
        let empty_arr = env.create_array(0)?;
        return Ok(empty_arr.into_unknown());
    }
    let first_arr: Object = unsafe { first.cast() }?;
    let first_len = first_arr.get_array_length()?;

    let mut other_arrays = Vec::new();
    for arr in &arrays[1..] {
        if arr.get_type()? == ValueType::Object && arr.is_array()? {
            let o: Object = unsafe { arr.cast() }?;
            other_arrays.push(o);
        }
    }

    let mut result_arr = env.create_array(0)?;
    let mut out_idx = 0;

    'outer: for i in 0..first_len {
        let item: Unknown = first_arr.get_element(i)?;
        for other in &other_arrays {
            let o_len = other.get_array_length()?;
            let mut found = false;
            for j in 0..o_len {
                let other_item: Unknown = other.get_element(j)?;
                let mut is_equal = false;
                unsafe {
                    napi::sys::napi_strict_equals(env.raw(), item.raw(), other_item.raw(), &mut is_equal);
                }
                if is_equal {
                    found = true;
                    break;
                }
            }
            if !found {
                continue 'outer;
            }
        }
        result_arr.set_element(out_idx, item)?;
        out_idx += 1;
    }
    Ok(result_arr.into_unknown())
}

