            let arr: Object = unsafe { arr_unknown.cast() }?;
            let len = arr.get_array_length()?;
            for i in 0..len {
                let item: Unknown = arr.get_element(i)?;
                let mut already_seen = false;
                for seen in &seen_items {
                    let mut is_equal = false;
                    unsafe {
                        napi::sys::napi_strict_equals(env.raw(), item.raw(), seen.raw(), &mut is_equal);
