{"file_text":"const jscodeshift = require('../core');
const matchNode = require('../matchNode');
const template = require('../template');
const argsParser = require('../argsParser');
const IgnoreFiles = require('../ignoreFiles');
const intersection = require('../utils/intersection');
const union = require('../utils/union');
const once = require('../utils/once');

describe('jscodeshift core and APIs', () => {
  test('basic transform and collection methods', () => {
    const code = 'const a = 1; const b = 2;';
    const root = jscodeshift(code);
    expect(root.find(jscodeshift.Identifier).size()).toBe(2);

    root.find(jscodeshift.Identifier, { name: 'a' }).forEach(path => {
      path.node.name = 'x';
    });

    expect(root.toSource()).toBe('const x = 1; const b = 2;');
  });

  test('variable declarator collection methods', () => {
    const code = 'var a = 1, b = 2; let c = 3;';
    const root = jscodeshift(code);
    const varDecls = root.findVariableDeclarators();
    expect(varDecls.size()).toBe(3);
    expect(varDecls.findVariableDeclarators('a').size()).toBe(1);
    expect(varDecls.findVariableDeclarators('b').size()).toBe(1);
    expect(varDecls.findVariableDeclarators('c').size()).toBe(1);
    expect(varDecls.findVariableDeclarators('nonexistent').size()).toBe(0);
  });

  test('jsx collection methods', () => {
    const code = '<div className="test"><span /></div>';
    const root = jscodeshift.withParser('babel')(code);
    const jsxElements = root.findJSXElements();
    expect(jsxElements.size()).toBe(2);
    expect(root.findJSXElementsByModuleName('div').size()).toBe(1);
    expect(root.findJSXElementsByModuleName('span').size()).toBe(1);
  });

  test('import declaration collection methods', () => {
    const code = 'import foo from "foo"; import { bar } from "bar";';
    const root = jscodeshift(code);
    expect(root.find(jscodeshift.ImportDeclaration).size()).toBe(2);
  });

  test('matchNode', () => {
    expect(matchNode({ a: 1, b: 2 }, { a: 1 })).toBe(true);
    expect(matchNode({ a: 1, b: 2 }, { a: 2 })).toBe(false);
    expect(matchNode({ a: [1, 2] }, { a: [1, 2] })).toBe(true);
    expect(matchNode({ a: [1, 2] }, { a: [1] })).toBe(false);
    expect(matchNode({ a: 1 }, (val) => val.a === 1)).toBe(true);
  });

  test('template', () => {
    const stmt = template.statement`const x = 42;`;
    expect(stmt.type).toBe('VariableDeclaration');

    const expr = template.expression`x + 1`;
    expect(expr.type).toBe('BinaryExpression');
  });

  test('utils intersection and union', () => {
    expect(intersection([1, 2, 3], [2, 3, 4])).toEqual([2, 3]);
    expect(union([1, 2], [2, 3])).toEqual([1, 2, 3]);
  });

  test('utils once', () => {
    let count = 0;
    const fn = once(() => ++count);
    expect(fn()).toBe(1);
    expect(fn()).toBe(1);
    expect(count).toBe(1);
  });

  test('argsParser', () => {
    const parser = argsParser.options({
      foo: {
        abbr: 'f',
        flag: true,
        default: false,
      },
      bar: {
        abbr: 'b',
        default: 'default-bar',
      }
    });

    const parsed = parser.parse(['-f', '--bar', 'custom', 'file1.js', 'file2.js']);
    expect(parsed.options.foo).toBe(true);
    expect(parsed.options.bar).toBe('custom');
    expect(parsed.positionalArguments).toEqual(['file1.js', 'file2.js']);
  });

  test('ignoreFiles', () => {
    const ignore = new IgnoreFiles();
    ignore.add('*.test.js');
    ignore.add('node_modules/');

    expect(ignore.shouldIgnore('foo.test.js')).toBe(true);
    expect(ignore.shouldIgnore('node_modules/foo.js')).toBe(true);
    expect(ignore.shouldIgnore('src/app.js')).toBe(false);
  });

  test('typescript and tsx parser', () => {
    const tsCode = 'const x: number = 42; interface Foo { bar: string; }';
    const root = jscodeshift.withParser('ts')(tsCode);
    expect(root.find(jscodeshift.Identifier, { name: 'x' }).size()).toBe(1);

    const tsxCode = 'const el: JSX.Element = <div id="test">Hello</div>;';
    const rootTsx = jscodeshift.withParser('tsx')(tsxCode);
    expect(rootTsx.findJSXElements('div').size()).toBe(1);
  });

  test('flow parser', () => {
    const flowCode = '// @flow\nfunction add(a: number, b: number): number { return a + b; }';
    const root = jscodeshift.withParser('flow')(flowCode);
    expect(root.find(jscodeshift.FunctionDeclaration).size()).toBe(1);
  });
});
