}

fn match_node_inner(env: &Env, haystack: &Unknown, needle: &Unknown) -> Result<bool> {
    let needle_type = needle.get_type()?;
    if needle_type == ValueType::Function {
        let func = unsafe { needle.cast::<Function>() }?;
        let res: Unknown = func.call(*haystack)?;
        let bool_res = res.coerce_to_bool()?.get_value()?;
        return Ok(bool_res);
    }

    if needle_type == ValueType::Null || needle_type == ValueType::Undefined {
        let mut is_equal = false;
        unsafe {
            let status = napi::sys::napi_strict_equals(env.raw(), haystack.raw(), needle.raw(), &mut is_equal);
            if status != napi::sys::Status::napi_ok {
                return Err(Error::from_status(Status::GenericFailure));
            }
        }
        return Ok(is_equal);
    }

    if needle_type != ValueType::Object {
        let mut is_equal = false;
        unsafe {
            let status = napi::sys::napi_strict_equals(env.raw(), haystack.raw(), needle.raw(), &mut is_equal);
            if status != napi::sys::Status::napi_ok {
                return Err(Error::from_status(Status::GenericFailure));
            }
        }
        return Ok(is_equal);
    }

    let haystack_type = haystack.get_type()?;
    if haystack_type != ValueType::Object {
        return Ok(false);
    }

    let needle_obj = unsafe { needle.cast::<Object>() }?;
    let haystack_obj = unsafe { haystack.cast::<Object>() }?;

    let needle_is_array = needle_obj.is_array()?;
    let haystack_is_array = haystack_obj.is_array()?;

    if needle_is_array {
        if !haystack_is_array {
            return Ok(false);
        }
        let n_len = needle_obj.get_array_length()?;
        let h_len = haystack_obj.get_array_length()?;
        if h_len < n_len {
            return Ok(false);
        }
        for i in 0..n_len {
            let h_val: Unknown = haystack_obj.get_element(i)?;
            let n_val: Unknown = needle_obj.get_element(i)?;
            if !match_node_inner(env, &h_val, &n_val)? {
                return Ok(false);
            }
        }
        return Ok(true);
    }

    if haystack_is_array {
        return Ok(false);
    }

    let keys = needle_obj.get_property_names()?;
    let len = keys.get_array_length()?;
    for i in 0..len {
        let prop_name: String = keys.get_element::<Unknown>(i)?.coerce_to_string()?.into_utf8()?.as_str()?.to_string();
        let h_val: Unknown = haystack_obj.get_named_property(&prop_name)?;
        let n_val: Unknown = needle_obj.get_named_property(&prop_name)?;
        if !match_node_inner(env, &h_val, &n_val)? {
            return Ok(false);
        }
    }

